class Solution {public:int solve(vector<int> a){int n=a.size();if(!n)return 0;vector<int> len(n,1),ways(n,1);int best=1;for(int i=0;i<n;i++){for(int j=0;j<i;j++)if(a[j]<a[i]){if(len[j]+1>len[i]){len[i]=len[j]+1;ways[i]=ways[j];}else if(len[j]+1==len[i])ways[i]=(ways[i]+ways[j])%1000000007;}best=max(best,len[i]);}int answer=0;for(int i=0;i<n;i++)if(len[i]==best)answer=(answer+ways[i])%1000000007;return answer;}};